import unittest
from app import quote

class QuoteTest(unittest.TestCase):
    def test_single(self):
        self.assertEqual(quote([{ "price_cents": 100, "quantity": 1}])["total_cents"], 110)
    def test_empty(self):
        self.assertEqual(quote([])["total_cents"], 0)

from pricing import total
from config import TAX_RATE

def quote(items):
    return {"total_cents": total(items, TAX_RATE)}

def total(items, tax_rate):
    subtotal = sum(item["price_cents"] for item in items)
    return subtotal + subtotal * tax_rate // 100

def unique_labels(labels):
    result = []
    for label in labels:
        if label not in result:
            result.append(label)
    return result
